const mappers = {
  payment: (r) => ({ id: r.id, name: r.name }),
  card: (r) => ({ ...mappers.payment(r), cardNumber: r.card_number }),
};

async function loadPayment(knex, id) {
  const row = await knex('payment').where({ id }).first();
  return (mappers[row.payment_type] ?? mappers.payment)(row);   // discriminator -> class
}
